const cdqPdfDownloadsV2264=window.__cdqPdfDownloadsV2264 instanceof Map
    ? window.__cdqPdfDownloadsV2264
    : new Map();
  window.__cdqPdfDownloadsV2264=cdqPdfDownloadsV2264;

  function cdqB64BytesV2264(base64){
    const bin=atob(String(base64||''));
    const out=new Uint8Array(bin.length);
    for(let i=0;i<bin.length;i++)out[i]=bin.charCodeAt(i);
    return out;
  }

  function cdqPdfCacheKeyV2264(id){
    return new Request(location.origin+'/__cdq_pdf_cache_v2264__/'+encodeURIComponent(String(id)));
  }

  async function cdqPdfCacheGetV2264(id){
    if(!('caches' in window))return null;
    try{
      const c=await caches.open('cdq-pdf-documents-v2264');
      const r=await Promise.race([
        c.match(cdqPdfCacheKeyV2264(id)),
        new Promise(function(resolve){setTimeout(function(){resolve(null);},800);})
      ]);
      if(!r)return null;
      const blob=await r.blob();
      if(!(blob instanceof Blob)||blob.size<5)return null;
      return {
        id:String(id),
        nom:r.headers.get('x-cdq-name')||'Rapport.pdf',
        revision:r.headers.get('x-cdq-revision')||'',
        taille:blob.size,
        blob:blob,
        cachedAt:Number(r.headers.get('x-cdq-cached-at')||0)
      };
    }catch(_){return null;}
  }

  function cdqPdfCachePutV2264(id,rec){
    if(!('caches' in window)||!rec||!(rec.blob instanceof Blob))return;
    Promise.resolve().then(async function(){
      try{
        const c=await caches.open('cdq-pdf-documents-v2264');
        const h=new Headers({
          'content-type':'application/pdf',
          'x-cdq-name':String(rec.nom||'Rapport.pdf'),
          'x-cdq-revision':String(rec.revision||''),
          'x-cdq-cached-at':String(Date.now())
        });
        await c.put(cdqPdfCacheKeyV2264(id),new Response(rec.blob,{status:200,headers:h}));
      }catch(_){}
    });
  }

  function cdqServerV2264(name,args){
    if(typeof window.cdqAppelServeur!=='function')
      return Promise.reject(new Error('Connexion au serveur CDQ indisponible.'));
    return window.cdqAppelServeur(name,Array.isArray(args)?args:[]);
  }

